class Allocator {
    vector<int> memory;
public:
    Allocator(int n):memory(n,0) {}
    int allocate(int size,int mID) {
        int run=0;
        for (int i=0;i<(int)memory.size();++i) {
            run=memory[i]==0?run+1:0;
            if (run==size) {
                int start=i-size+1;
                for (int j=start;j<=i;++j) memory[j]=mID;
                return start;
            }
        }
        return -1;
    }
    int freeMemory(int mID) {
        int count=0;
        for (int& x:memory) if (x==mID) {x=0;++count;}
        return count;
    }
};
